import os
from torchvision import datasets, transforms
from torch.utils.data import DataLoader, random_split
from datasets import load_dataset

DATA_CONFIG = {
    'CIFAR-10': {
        'num_classes': 10,
        'input_shape': (3, 32, 32),
        'metrics': ['accuracy', 'convergence_speed', 'final_loss']
    },
    'DEAP': {
        'num_classes': None,  # Define based on specific task
        'input_shape': None,  # Define based on specific task
        'metrics': ['accuracy', 'f1_score']
    },
    'SEED': {
        'num_classes': None,  # Define based on specific task
        'input_shape': None,  # Define based on specific task
        'metrics': ['accuracy', 'f1_score']
    }
}

def get_datasets(data_root='/workspace/data') -> dict:
    datasets_dict = {}

    try:
        # CIFAR-10 (tier 1)
        transform_train = transforms.Compose([
            transforms.RandomHorizontalFlip(),
            transforms.RandomCrop(32, padding=4),
            transforms.ToTensor(),
            transforms.Normalize((0.4914, 0.4822, 0.4465), (0.2023, 0.1994, 0.2010))
        ])
        transform_test = transforms.Compose([
            transforms.ToTensor(),
            transforms.Normalize((0.4914, 0.4822, 0.4465), (0.2023, 0.1994, 0.2010))
        ])

        cifar10_full = datasets.CIFAR10(root=data_root, train=True, transform=transform_train, download=False)
        cifar10_test = datasets.CIFAR10(root=data_root, train=False, transform=transform_test, download=False)

        train_size = int(0.8 * len(cifar10_full))
        val_size = len(cifar10_full) - train_size
        cifar10_train, cifar10_val = random_split(cifar10_full, [train_size, val_size])

        datasets_dict['train'] = DataLoader(cifar10_train, batch_size=64, shuffle=True, num_workers=4)
        datasets_dict['val'] = DataLoader(cifar10_val, batch_size=64, shuffle=False, num_workers=4)
        datasets_dict['test'] = DataLoader(cifar10_test, batch_size=64, shuffle=False, num_workers=4)

    except Exception as e:
        raise RuntimeError(f"Error loading CIFAR-10 dataset: {e}")

    try:
        # DEAP Dataset (tier 2)
        deap_dataset = load_dataset('deap', split='train', cache_dir=data_root)
        datasets_dict['deap'] = deap_dataset  # Modify as per specific requirements

    except Exception as e:
        raise RuntimeError(f"Error loading DEAP dataset: {e}")

    try:
        # SEED Dataset (tier 2)
        seed_dataset = load_dataset('seed', split='train', cache_dir=data_root)
        datasets_dict['seed'] = seed_dataset  # Modify as per specific requirements

    except Exception as e:
        raise RuntimeError(f"Error loading SEED dataset: {e}")

    return datasets_dict

