import torch
import torch.nn as nn
from torch_geometric.nn import GCNConv, GATConv, SAGEConv

BASELINES_CONFIG = {
    "GCN": {
        "param_count": "Depends on input dimensions and layers",
        "paper": "Kipf & Welling, Semi-Supervised Classification with GCN, ICLR 2017",
    },
    "GAT": {
        "param_count": "Depends on input dimensions and layers",
        "paper": "Velickovic et al., Graph Attention Networks, ICLR 2018",
    },
    "GraphSAGE": {
        "param_count": "Depends on input dimensions and layers",
        "paper": "Hamilton et al., Inductive Representation Learning, NeurIPS 2017",
    },
    "Adam": {
        "param_count": "Optimizer, no direct param count",
        "paper": "Kingma & Ba, Adam, ICLR 2015",
    },
}

class GCNModel(nn.Module):
    def __init__(self, input_dim, hidden_dim, num_classes):
        super(GCNModel, self).__init__()
        self.conv1 = GCNConv(input_dim, hidden_dim)
        self.conv2 = GCNConv(hidden_dim, num_classes)

    def forward(self, x, edge_index):
        x = self.conv1(x, edge_index)
        x = torch.relu(x)
        x = self.conv2(x, edge_index)
        return x


class GATModel(nn.Module):
    def __init__(self, input_dim, hidden_dim, num_classes, heads=8):
        super(GATModel, self).__init__()
        self.conv1 = GATConv(input_dim, hidden_dim, heads=heads)
        self.conv2 = GATConv(hidden_dim * heads, num_classes, heads=1)

    def forward(self, x, edge_index):
        x = self.conv1(x, edge_index)
        x = torch.relu(x)
        x = self.conv2(x, edge_index)
        return x


class GraphSAGEModel(nn.Module):
    def __init__(self, input_dim, hidden_dim, num_classes):
        super(GraphSAGEModel, self).__init__()
        self.conv1 = SAGEConv(input_dim, hidden_dim)
        self.conv2 = SAGEConv(hidden_dim, num_classes)

    def forward(self, x, edge_index):
        x = self.conv1(x, edge_index)
        x = torch.relu(x)
        x = self.conv2(x, edge_index)
        return x


def get_baselines(num_classes, device='cuda') -> dict:
    baselines = {}

    # Define input and hidden dimensions for the models
    input_dim = 3  # CIFAR-10 images have 3 channels
    hidden_dim = 64

    # Instantiate GCN
    try:
        gcn_model = GCNModel(input_dim, hidden_dim, num_classes).to(device)
        baselines["GCN"] = gcn_model
    except ImportError:
        print("torch_geometric is not installed. Skipping GCN baseline.")

    # Instantiate GAT
    try:
        gat_model = GATModel(input_dim, hidden_dim, num_classes).to(device)
        baselines["GAT"] = gat_model
    except ImportError:
        print("torch_geometric is not installed. Skipping GAT baseline.")

    # Instantiate GraphSAGE
    try:
        sage_model = GraphSAGEModel(input_dim, hidden_dim, num_classes).to(device)
        baselines["GraphSAGE"] = sage_model
    except ImportError:
        print("torch_geometric is not installed. Skipping GraphSAGE baseline.")

    # Adam optimizer (not a model but included for completeness)
    try:
        dummy_params = torch.nn.ParameterList([torch.nn.Parameter(torch.randn(1))])
        adam_optimizer = torch.optim.Adam(dummy_params, lr=1e-3, weight_decay=1e-4)
        baselines["Adam"] = adam_optimizer
    except ImportError:
        print("torch is not installed. Skipping Adam optimizer.")

    return baselines
